#include "unity.h"
#include "power/charger.h"
#include "power/fuel_gauge.h"
#include "fakes/charger_hw.h"

void test_full_charge_reaches_100_percent(void)
{
    fake_usb_present(true);
    fake_battery_mv(4185);
    fake_charge_current_ma(62); /* the IC's own termination point */
    for (int i = 0; i < 10; i++) charger_poll();
    TEST_ASSERT_TRUE(g_fuel_gauge.charge_complete);
    TEST_ASSERT_EQUAL_UINT8(100, battery_percent(&g_fuel_gauge));
}

void test_unplugged_clears_charge_complete(void)
{
    g_fuel_gauge.charge_complete = true;
    fake_usb_present(false);
    charger_poll();
    TEST_ASSERT_FALSE(g_fuel_gauge.charge_complete);
}
